import React from 'react';
import Header from './Header';
import './UserPage.css';
import Footer from './Footer';
import user from './User.jpg'

function User() {
    return(
        <div className='UserPage'>
            <Header/>
            <h1>User Info</h1>
            <div className='Image'>
                <img src={user} />
            </div>
            <div className='About'>
                <h4>Name:</h4><p></p>
            </div>
            <Footer/>
        </div>
    );
}


export default User;
